import {
    Component,
    Input,
    OnChanges,
    OnInit,
    SimpleChanges,
} from '@angular/core';
import { MatDialog } from '@angular/material/dialog';
import { ActivatedRoute, RouterModule } from '@angular/router';
import {
    SettingsService,
    currentUser,
    formatDuration,
    formatRecurrence,
    fromBookingRecurrence,
    i18n,
} from '@placeos/common';
import { addMinutes, format, isSameDay } from 'date-fns';
import { map } from 'rxjs/operators';

import { CommonModule } from '@angular/common';
import { MatTooltipModule } from '@angular/material/tooltip';
import { AsyncHandler } from 'libs/common/src/lib/async-handler.class';
import { IconComponent } from 'libs/components/src/lib/icon.component';
import { StatusPillComponent } from 'libs/components/src/lib/status-pill.component';
import { TranslatePipe } from 'libs/components/src/lib/translate.pipe';
import { OrganisationService } from 'libs/organisation/src/lib/organisation.service';
import { GroupEventDetailsModalComponent } from '../../../events/src/lib/group-event-details-modal.component';
import { BookingDetailsModalComponent } from './booking-details-modal.component';
import { Booking } from './booking.class';
import { ParkingService } from './parking.service';

@Component({
    selector: 'booking-card',
    template: `
        <h4 class="mb-2 flex items-center" *ngIf="booking">
            <span *ngIf="show_day" day>{{ day }},&nbsp;</span>
            {{ booking?.date | date: time_format }}
            <span class="px-2 text-xs"
                >({{ booking?.date | date: 'zzzz' }})</span
            >
        </h4>
        <a
            name="view-booking-details"
            class="relative w-full cursor-pointer overflow-hidden"
            [routerLink]="['./']"
            [queryParams]="{ booking: booking?.id }"
            (click)="viewDetails()"
            *ngIf="booking"
        >
            <div
                class="relative w-full rounded-xl border border-base-300 bg-base-100 py-4 shadow"
            >
                <h4 class="px-4 text-lg">{{ booking?.title }}</h4>
                <div class="mx-4 my-2 flex items-center space-x-2">
                    <status-pill [status]="status">{{ period }}</status-pill>
                    <icon
                        *ngIf="booking.instance"
                        class="text-2xl"
                        [matTooltip]="recurr_tooltip"
                        >event_repeat</icon
                    >
                </div>
                <div
                    class="divide-base-200-500 flex flex-col flex-wrap space-y-2 py-2 sm:flex-row sm:space-y-0 sm:divide-x"
                >
                    <div class="flex max-w-[33%] items-center px-4">
                        @switch (type) {
                            @case ('desk') {
                                <icon
                                    [matTooltip]="'RESOURCE.DESK' | translate"
                                    matTooltipPosition="right"
                                    >desk</icon
                                >
                            }
                            @case ('locker') {
                                <icon
                                    [matTooltip]="'RESOURCE.LOCKER' | translate"
                                    matTooltipPosition="right"
                                    >lock</icon
                                >
                            }
                            @case ('parking') {
                                <icon
                                    [matTooltip]="
                                        'RESOURCE.PARKING' | translate
                                    "
                                    matTooltipPosition="right"
                                    >drive_eta</icon
                                >
                            }
                            @case ('visitor') {
                                <icon
                                    [matTooltip]="
                                        'RESOURCE.VISITOR' | translate
                                    "
                                    matTooltipPosition="right"
                                    >people</icon
                                >
                            }
                            @default {
                                <icon>book</icon>
                            }
                        }
                        <div class="mx-2 w-1/2 flex-1 truncate">
                            {{
                                raw_description ||
                                    booking?.asset_name ||
                                    booking?.asset_id
                            }}
                        </div>
                    </div>
                    <div class="flex items-center px-4" *ngIf="location">
                        <icon>place</icon>
                        <div class="mx-2 truncate">{{ location }}</div>
                    </div>
                </div>
                <icon
                    class="absolute right-1 top-1/2 -translate-y-1/2 text-4xl"
                >
                    chevron_right
                </icon>
                <div
                    class="bg-warning/50 absolute right-2 top-2 rounded-xl px-2 py-1 text-xs"
                    *ngIf="
                        !for_current_user &&
                        booking?.booking_type !== 'group-event'
                    "
                >
                    {{ 'BOOKINGS.ASSOCIATE' | translate }}
                </div>
                <div
                    class="bg-warning/50 absolute right-2 top-2 rounded-xl px-2 py-1 text-xs"
                    *ngIf="booking?.booking_type === 'group-event'"
                >
                    {{ 'BOOKINGS.EVENT' | translate }}
                </div>
                <div
                    class="bg-warning/50 absolute right-2 top-2 rounded-xl px-2 py-1 text-xs"
                    *ngIf="is_reserved_parking_space | async"
                >
                    {{
                        (booking.status !== 'declined'
                            ? 'BOOKINGS.RESERVED'
                            : 'BOOKINGS.RELEASED'
                        ) | translate
                    }}
                </div>
            </div>
        </a>
    `,
    styles: [
        `
            :host {
                display: block;
                width: 100%;
                position: relative;
            }
        `,
    ],
    imports: [
        CommonModule,
        TranslatePipe,
        IconComponent,
        StatusPillComponent,
        RouterModule,
        MatTooltipModule,
    ],
})
export class BookingCardComponent
    extends AsyncHandler
    implements OnInit, OnChanges
{
    @Input() public booking: Booking;
    @Input() public show_day = false;
    @Input() public edit_fn = (i) => null;
    @Input() public remove_fn = (i, s?) => null;
    @Input() public end_fn = (i) => null;

    public raw_description = '';

    public readonly is_reserved_parking_space =
        this._parking.assigned_space.pipe(
            map(
                (space) =>
                    this.booking.booking_type === 'parking' &&
                    space &&
                    this.booking.asset_id === space.id,
            ),
        );

    public get for_current_user() {
        return (
            this.booking?.user_email.toLowerCase() ===
            currentUser()?.email.toLowerCase()
        );
    }

    public get time_format() {
        return this._settings.time_format;
    }

    public get status() {
        if (this.booking?.is_done) return 'neutral';
        if (this.booking?.status === 'approved') return 'success';
        if (this.booking?.status === 'declined') return 'error';
        if (this.booking?.status === 'cancelled') return 'error';
        if (this.booking?.status === 'tentative') return 'warning';
        return 'warning';
    }

    public get recurr_tooltip() {
        return (
            formatRecurrence(fromBookingRecurrence(this.booking)) ||
            i18n('CALENDAR_EVENT.RECURRING_TOOLTIP')
        );
    }

    constructor(
        private _dialog: MatDialog,
        private _route: ActivatedRoute,
        private _org: OrganisationService,
        private _settings: SettingsService,
        private _parking: ParkingService,
    ) {
        super();
    }

    public ngOnInit() {
        this.subscription(
            'route.query',
            this._route.queryParamMap.subscribe((params) =>
                params.has('booking') &&
                this.booking?.id === params.get('event')
                    ? this.viewDetails()
                    : '',
            ),
        );
    }

    public ngOnChanges(changes: SimpleChanges) {
        if (changes.booking) {
            this.raw_description = this.removeHtmlTags(
                this.booking?.description,
            );
        }
    }

    public get type() {
        return this.booking.type;
    }

    public get day() {
        const date = this.booking?.date || Date.now();
        const is_today = isSameDay(Date.now(), date);
        return `${is_today ? i18n('COMMON.TODAY') : format(date, 'EEEE')}`;
    }

    public get location() {
        const level = this._org.levelWithID(this.booking?.zones || []);
        return `${level?.display_name || level?.name || ''}`;
    }

    public get period() {
        if (this.booking?.is_all_day) return i18n('COMMON.ALL_DAY');
        const start = this.booking?.date || Date.now();
        const duration = this.booking?.duration || 60;
        const end = addMinutes(start, duration);
        const dur = formatDuration({
            hours: Math.floor(duration / 60),
            minutes: duration % 60,
        })
            .replace(' hour', 'hr')
            .replace(' minute', 'min');
        return `${format(start, this.time_format)} - ${format(
            end,
            this.time_format,
        )} (${dur})`;
    }

    public removeHtmlTags(html: string) {
        const doc = new DOMParser().parseFromString(html, 'text/html');
        return doc.body.textContent || '';
    }

    public viewDetails() {
        if (!this.booking) return;
        this.timeout('open', () => {
            const view_component: any =
                this.booking.booking_type === 'group-event'
                    ? GroupEventDetailsModalComponent
                    : BookingDetailsModalComponent;
            const data = {
                booking:
                    this.booking.booking_type === 'group-event'
                        ? { booking: this.booking, concierge: false }
                        : this.booking,
                edit_fn: this.edit_fn,
                remove_fn: this.remove_fn,
                end_fn: this.end_fn,
            };
            this._dialog.open(view_component, { data });
        });
    }
}
